<script setup>
import {onMounted,ref} from 'vue'
import {Doughnut,Bar} from 'vue-chartjs'
import {Chart as ChartJS,ArcElement,BarElement,CategoryScale,LinearScale,Tooltip,Legend} from 'chart.js'
import PageHeader from '../components/PageHeader.vue'
import {api} from '../lib/api.js'
ChartJS.register(ArcElement,BarElement,CategoryScale,LinearScale,Tooltip,Legend)
const stats=ref(null),coverage=ref([]),events=ref([]),error=ref('')
onMounted(async()=>{try{[stats.value,coverage.value,events.value]=await Promise.all([api('/reports/dashboard'),api('/reports/coverage'),api('/logs/search')])}catch(e){error.value=e.message}})
const donutOptions={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{color:'#aab8c8',boxWidth:10}}},cutout:'75%'}
const barOptions={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{color:'#8494a8'},grid:{display:false}},y:{ticks:{color:'#8494a8'},grid:{color:'#26354a'}}}}
</script>
<template><div class="view"><PageHeader eyebrow="COMMAND CENTER / OVERVIEW" title="Fleet overview" description="Operational status across your Windows firewall estate"><router-link to="/inventory" class="button secondary"><i class="mdi mdi-plus"></i> Add node</router-link><router-link to="/policies" class="button primary"><i class="mdi mdi-source-branch"></i> Policy studio</router-link></PageHeader><div v-if="error" class="error-msg">{{error}}</div><template v-if="stats"><div class="metric-grid"><div class="metric glass"><div class="metric-top"><span>MANAGED NODES</span><i class="mdi mdi-server-network"></i></div><strong>{{stats.totalNodes}}</strong><small><span class="online-dot"></span> {{stats.reachableNodes}} reachable · {{stats.agentsOnline}} agents online / {{stats.agentsOffline}} offline</small></div><div class="metric glass"><div class="metric-top"><span>ACTIVE POLICIES</span><i class="mdi mdi-shield-check-outline"></i></div><strong>{{stats.policies}}</strong><small>Version controlled</small></div><div class="metric glass"><div class="metric-top"><span>VERIFIER PASS RATE</span><i class="mdi mdi-check-decagram-outline"></i></div><strong>{{stats.verifierPassRate??'—'}}<span v-if="stats.verifierPassRate!==null">%</span></strong><small>{{stats.verifierInconclusive}} inconclusive checks</small></div><div class="metric glass"><div class="metric-top"><span>FAILED APPLIES</span><i class="mdi mdi-alert-circle-outline"></i></div><strong :class="{'danger-text':stats.failedApplies}">{{stats.failedApplies}}</strong><small>Review apply history</small></div></div><div class="dashboard-grid"><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">POSTURE</span><h2>Fleet coverage</h2></div><router-link to="/reports">VIEW REPORT <i class="mdi mdi-arrow-right"></i></router-link></div><div class="coverage-content"><div class="chart-box"><Doughnut :data="{labels:['Policy assigned','Uncovered'],datasets:[{data:[coverage.filter(n=>n.policy_count>0).length,coverage.filter(n=>n.policy_count===0).length],backgroundColor:['#55e8bb','#27374d'],borderWidth:0}]}" :options="donutOptions" /></div><div class="coverage-list"><div><span class="legend-dot green"></span> Protected nodes <strong>{{coverage.filter(n=>n.policy_count>0).length}}</strong></div><div><span class="legend-dot gray"></span> Missing policy <strong>{{coverage.filter(n=>n.policy_count===0).length}}</strong></div><div><span class="legend-dot red"></span> Observed drift <strong>{{coverage.filter(n=>n.drift_status==='drift').length}}</strong></div></div></div></section><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">TELEMETRY</span><h2>Top denied ports</h2></div><router-link to="/logs">EXPLORE LOGS <i class="mdi mdi-arrow-right"></i></router-link></div><div class="chart-box bar"><Bar v-if="stats.deniedPorts.length" :data="{labels:stats.deniedPorts.map(x=>x.dst_port||'Unknown'),datasets:[{data:stats.deniedPorts.map(x=>x.count),backgroundColor:'#8a87fa',borderRadius:4}]}" :options="barOptions" /><div v-else class="empty-chart"><i class="mdi mdi-chart-bar"></i><span>No denied traffic has been collected yet</span></div></div></section></div><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">LATEST ACTIVITY</span><h2>Recent security events</h2></div><router-link to="/logs">ALL EVENTS <i class="mdi mdi-arrow-right"></i></router-link></div><div class="table-wrap"><table><thead><tr><th>TIME</th><th>NODE</th><th>ACTION</th><th>SOURCE</th><th>DESTINATION</th><th>PORT</th></tr></thead><tbody><tr v-for="event in events.slice(0,6)" :key="event.id"><td>{{new Date(event.received_at).toLocaleString()}}</td><td class="mono">{{event.node_id?.slice(0,8)}}</td><td><span class="status" :class="event.action">{{event.action}}</span></td><td class="mono">{{event.src_ip||'—'}}</td><td class="mono">{{event.dst_ip||'—'}}</td><td class="mono">{{event.dst_port||'—'}}</td></tr><tr v-if="!events.length"><td colspan="6" class="empty-table">No events yet. Configure log collection on a node to begin.</td></tr></tbody></table></div></section></template></div></template>
